<?php defined('BASEPATH') or exit('No direct script access allowed'); $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); $section=$native_client_section??['title'=>'Cliente','columns'=>[],'rows'=>[]]; ?>
<h4 class="customer-profile-group-heading"><?= $e($section['title']); ?></h4><p class="text-muted">A seção usa os dados e as permissões da empresa atual; registros de outra empresa não são projetados.</p>
<div class="table-responsive"><table class="table"><thead><tr><?php foreach($section['columns'] as$column){ ?><th><?= $e(ucwords(str_replace('_',' ',$column))); ?></th><?php } ?></tr></thead><tbody><?php foreach($section['rows'] as$row){ ?><tr><?php foreach($section['columns'] as$column){ ?><td><?= $e($row[$column]??''); ?></td><?php } ?></tr><?php } ?><?php if(empty($section['rows'])){ ?><tr><td colspan="<?= max(1,count($section['columns'])); ?>">Nenhum registro nesta seção.</td></tr><?php } ?></tbody></table></div>
